"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[68912],{45473:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"RockController","desc":"Renders Rock Hazards. On `RockSpawn` it takes a pooled copy of the rock model,\\nscales it, applies the biome look (eruption rocks: `RockConfig.Eruption`\'s\\nlook and gravity), and moves + spins it every frame with\\n`RockMath.positionAt` (the server\'s formula). On `EruptionStart` it plays a\\nfire pillar from `ReplicatedStorage.EruptionPillar`. On `RockRemoved` it plays the\\nVFX/SFX for the reason and returns the model to the pool. Shield hits are\\ndrawn by `TrainShieldDomeController` from `TrainShieldHit`, not here.","realm":["Client"],"source":{"line":14,"path":"src/StarterPlayer/StarterPlayerScripts/RockController.client.luau"}}')}}]);